examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    VStack(spacing: theme.spacing.space2) {
        MonarchButton({{file}}, variant: .ghost) {}
        Text("Touch and hold the file for its actions.")
            .monarchTextStyle(.caption)
    }
    .frame(maxWidth: .infinity, minHeight: 128)
    .padding(theme.spacing.space4)
    .background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: theme.radius.lg))
    .contextMenu {
        Button({{items.0.label}}, systemImage: "pencil") { last = {{items.0.label}} }
        Button({{items.1.label}}) { last = {{items.1.label}} }
        Divider()
        Button({{items.2.label}}, systemImage: "trash", role: .destructive) { last = {{items.2.label}} }
    }
    .accessibilityLabel({{menuLabel}})
    Text("Last action: \(last)")
        .monarchTextStyle(.caption)
}
.frame(maxWidth: 384)

